mapper.select:
SELECT a.real_stock_mst_id ,a.real_stock_date ,c.code_nm AS item_type_name ,CASE WHEN COUNT(DISTINCT b.item_cd) = 0 THEN '' WHEN COUNT(DISTINCT b.item_cd) = 1 THEN MAX(firstItem.item_name) ELSE CONCAT(MAX(firstItem.item_name), ' 외 ', COUNT(DISTINCT b.item_cd) - 1, '건') END AS item_name ,dbo.getStorageName(a.storage_cd) AS storage_name ,u.member_nm AS manager_name ,c1.code_nm AS area_name ,SUM(isnull(b.doc_stock_qty, 0)) AS doc_stock_qty ,SUM(isnull(b.reql_stock_qty, 0)) AS reql_stock_qty ,SUM(isnull(b.reql_stock_qty, 0))- SUM(isnull(b.doc_stock_qty, 0)) as diffStockQty ,a.end_yn FROM tb_real_stock_mst a left JOIN tb_real_stock_item b ON a.real_stock_mst_id = b.real_stock_mst_id left JOIN tb_item_mst i ON i.item_cd = b.item_cd LEFT JOIN tb_common_code c ON c.code = a.item_type_cd AND c.com_type_cd = 'item_type_cd' LEFT JOIN tb_common_code c1 ON c1.code = a.area_cd AND c1.com_type_cd = 'area' LEFT JOIN tb_users u ON u.user_id = a.manager_id OUTER APPLY ( SELECT TOP 1 im.item_name FROM tb_real_stock_item ri JOIN tb_item_mst im ON im.item_cd = ri.item_cd WHERE ri.real_stock_mst_id = a.real_stock_mst_id ORDER BY ri.item_cd ASC ) firstItem WHERE a.real_stock_date BETWEEN #{strDate} AND #{endDate}
AND a.item_type_cd = #{itemTypeCd}
AND a.area_cd = #{areaCd}
AND a.storage_cd = #{storageCd}
AND b.item_cd LIKE '%#{itemCd}%'
AND i.item_name LIKE '%#{itemName}%'
GROUP BY a.real_stock_mst_id ,a.real_stock_date ,c.code_nm ,a.storage_cd ,u.member_nm ,c1.code_nm,a.end_yn ORDER BY a.real_stock_mst_id DESC

mapper.update:
update tb_real_stock_item
set    reql_stock_qty = #{reqlStockQty}
      ,etc            = #{etc}
      ,upd_id         = #{userId}
      ,upd_dt         = getDate()
where  real_stock_item_id = #{realStockItemId}

update tb_real_stock_mst
set    tran_id = #{tranId}
      ,end_yn  = 'Y'
      ,upd_id  = #{userId}
      ,upd_dt  = getDate()
where  real_stock_mst_id = #{realStockMstId}
